import type { Difficulty } from "./constants.js";
import type { ImprovementPlanDto, SuggestedPracticeProblem } from "./interviews.js";

export const AI_EVALUATION_DISCLAIMER =
  "This interview report and all associated scores, feedback, and improvement suggestions are generated by an AI evaluation model based on interview rubrics. They represent subjective performance guidance and should not be confused with objective compiler or automated test runner verdicts.";

