export function generateImprovementPlan(input: {
  topic: string;
  weaknesses: string[];
  recommendations: string[];
  difficulty: Difficulty;
}): ImprovementPlanDto {
  const { topic, weaknesses, recommendations, difficulty } = input;

  const combinedCorpus = [topic, ...weaknesses, ...recommendations].join(" ").toLowerCase();

  // Score candidate problems by keyword matching
  const scored = CATALOG_CANDIDATES.map((candidate) => {
    let score = 0;
    for (const kw of candidate.keywords) {
      if (combinedCorpus.includes(kw)) {
        score += 2;
      }
    }
    // Slight boost if matching difficulty
    if (candidate.difficulty === difficulty) {
      score += 1;
    }
    return { candidate, score };
  });

  // Sort descending by score, tie-break by difficulty preference
  scored.sort((a, b) => b.score - a.score);

  // Pick top 3 unique problems
  const selected: SuggestedPracticeProblem[] = scored.slice(0, 3).map(({ candidate }) => ({
    slug: candidate.slug,
    title: candidate.title,
    difficulty: candidate.difficulty,
    reason: candidate.defaultReason,
  }));

  // Target areas extracted from weaknesses or default
  const targetAreas =
    weaknesses.length > 0
      ? weaknesses.slice(0, 3)
      : [
          `Solidifying core fundamentals in ${topic}`,
          "Articulating trade-offs and complexity proactively",
          "Working through concrete edge cases before presenting final answers",
        ];

  // Actionable advice
  const keyAdvice =
    recommendations.length > 0
      ? recommendations.slice(0, 3)
      : [
          "Practice stating your assumptions and space/time complexity bounds upfront.",
          "Break down complex explanations into structured step-by-step paragraphs.",
          "Solve related practice problems under timed conditions to build speed.",
        ];

  return {
    targetAreas,
    suggestedProblems: selected,
    keyAdvice,
    disclaimer: AI_EVALUATION_DISCLAIMER,
  };
}
